  const textExts = new Set([
    '.txt', '.md', '.json', '.xml', '.html', '.htm', '.css', '.js', '.mjs',
    '.c', '.h', '.py', '.sh', '.yml', '.yaml', '.toml', '.ini', '.cfg',
    '.java', '.go', '.rs', '.ts', '.jsx', '.tsx', '.svg', '.csv', '.env',
  ]);
  return textExts.has(ext) ? 'text' : 'binary';
}

function normalizeContent(buf) {
  // 统一 CRLF/CR -> LF，保证跨平台构建代理产生相同摘要；同时校验 UTF-8（text 类）。
  const normalized = Buffer.from(
    buf.toString('utf8').replace(/\r\n?/g, '\n'),
    'utf8',
  );
  return normalized;
}

// ---------------------------------------------------------------------------
// 摘要
// ---------------------------------------------------------------------------

export function hashBytes(buf) {
  return createHash(HASH_ALGORITHM).update(buf).digest();
}

export function hashHex(buf) {
  return createHash(HASH_ALGORITHM).update(buf).digest('hex');
}

// 整个产物的稳定内容摘要：对排序后的文件记录流做哈希。
// 记录为「相对路径|大小|sha256」，任何字节变化或增删文件都会改变结果。
export function computeArtifactDigest(records) {
  const h = createHash(HASH_ALGORITHM);
  for (const r of records) {
    h.update(`file|${r.path}|${r.size}|${r.sha256}\n`, 'utf8');
  }
  return h.digest('hex');
}

// ---------------------------------------------------------------------------
// 语义包（证明 + 清单）
// ---------------------------------------------------------------------------

// 从目录构建证明与清单所需全部数据。timestamp 由调用方注入，便于测试与复现。
export function buildModel(rootDir, excludedDir, timestamp) {
  const resolvedRoot = path.resolve(rootDir);
  const records = scanDirectory(resolvedRoot, excludedDir);
  const artifactDigest = computeArtifactDigest(records);
  const name = path.basename(resolvedRoot);
  const totalSize = records.reduce((sum, r) => sum + r.size, 0);

  // 证明主体：不含 signature 字段，时间戳独立成字段，不参与文件级摘要。
  const proof = {
    artifact_digest: artifactDigest,
    artifact_name: name,
    file_count: records.length,
    generated_at: timestamp,
    total_size: totalSize,
    version: PROOF_VERSION,
  };

  // 签名/比较的规范字节：仅包含上述字段，时间戳在其中但不影响文件摘要。
  const proofCanonical = stableJSONStringify(proof);
  const sbom = makeSBOM(records, { name, totalSize, artifactDigest });
  return { proof, proofCanonical, sbom, records };
}

function makeSBOM(records, meta) {
  return {
    artifact_digest: meta.artifactDigest,
    artifact_name: meta.name,
    files: records.map((r) => ({
      path: r.path,
      sha256: r.sha256,
      size: r.size,
      type: r.type,
         })),
    file_count: records.length,
    total_size: meta.totalSize,
    version: PROOF_VERSION,
  };
}

// ---------------------------------------------------------------------------
// 密钥与签名（Ed25519，PEM）
// ---------------------------------------------------------------------------

export function generateKeyPair() {
  return generateKeyPairSync('ed25519', {
    privateKey: { format: 'pem' },
    publicKey: { format: 'pem' },
  });
}

export function loadPrivateKey(pemPath) {
  let pem;
  try {
    pem = readFileSync(pemPath);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw fail(ErrorCode.KEY_NOT_FOUND, '私钥不存在', { path: pemPath });
    }
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      throw fail(ErrorCode.PERMISSION_DENIED, '私钥权限不足', {
        path: pemPath,
      });
    }
    throw err;
  }
  try {
    return createPrivateKey(pem);
  } catch {
    // 私钥内容无法解析时与其他密钥问题同归 KEY_NOT_FOUND（无法定位可用密钥）。
    throw fail(ErrorCode.KEY_NOT_FOUND, '私钥格式无效', { path: pemPath });
  }
}

export function loadPublicKey(pemPath) {
  let pem;
  try {
    pem = readFileSync(pemPath);
  } catch ( err) {
    if (err.code === 'ENOENT') {
      throw fail(ErrorCode.KEY_NOT_FOUND, '公钥不存在', { path: pemPath });
    }
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      throw fail(ErrorCode.PERMISSION_DENIED, '公钥权限不足', {
        path: pemPath,
      });
    }
    throw err;
  }
  try {
    return createPublicKey(pem);
  } catch {
    throw fail(ErrorCode.KEY_NOT_FOUND, '公钥格式无效', { path: pemPath });
  }
}

export function signProof(privateKey, canonicalBytes) {
  return cryptoSign(null, canonicalBytes, privateKey);
}

// 严格校验：数据或公钥错误均返回 false，由调用方映射为 SIGNATURE_INVALID。
export function checkSignature(publicKey, canonicalBytes, signatureBuf) {
  try {
    return cryptoVerify(null, canonicalBytes, publicKey, signatureBuf);
  } catch {
    return false;
  }
}

// 签名以原始字节形式保存为 .sig（Ed25519 固定 64 字节），并附 metadata JSON。
export function writeOutputFile(filePath, data) {
  try {
    writeFileSync(filePath, data);
  } catch (err) {
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      throw fail(ErrorCode.PERMISSION_DENIED, '输出目录权限不足', {
        path: filePath,
      });
    }
    throw err;
  }
}

export function chmod600(p) {
  try {
    chmodSync(p, 0o600);
  } catch {
    // 非关键路径，权限设置失败不阻断生成。
  }
}

// 读取并粗略校验签名文件：必须是 Ed25519 的 64 字节。
export function loadSignature(sigPath) {
  let buf;
  try {
    buf = readFileSync(sigPath);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw fail(ErrorCode.INPUT_NOT_FOUND, '签名文件不存在', {
        path: sigPath,
      });
    }
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      throw fail(ErrorCode.PERMISSION_DENIED, '签名文件权限不足', {
        path: sigPath,
      });
    }
    throw err;
  }
  if (!Buffer.isBuffer(buf) || buf.length !== 64) {
    throw fail(ErrorCode.PROOF_INVALID, '签名格式非法（应为 64 字节 Ed25519 签名）', {
      path: sigPath,
      length: buf.length,
    });
  }
  return buf;
}

// ---------------------------------------------------------------------------
// 证明解析与校验
// ---------------------------------------------------------------------------

const REQUIRED_PROOF_FIELDS = [
  'artifact_digest',
  'artifact_name',
  'file_count',
  'generated_at',
  'total_size',
  'version',
];

export function parseProof(raw) {
  let obj;
  try {
    obj = JSON.parse(raw.toString('utf8'));
  } catch {
    throw fail(ErrorCode.PROOF_INVALID, '证明不是合法的 JSON', null);
  }
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    throw fail(ErrorCode.PROOF_INVALID, '证明结构非法', null);
  }
  for (const f of REQUIRED_FIELDS) {
    if (!(f in obj)) {
      throw fail(ErrorCode.PROOF_INVALID, `证明缺少字段: ${f}`, {
        missing: f,
      });
    }
  }
  if (
    typeof obj.artifact_digest !== 'string' ||
    !/^[0-9a-f]{64}$/i.test(obj.artifact_digest)
  ) {
    throw fail(ErrorCode.PROOF_INVALID, '证明中的产物摘要非法', null);
  }
  if (typeof obj.version !== 'string' || obj.version !== PROOF_VERSION) {
    throw fail(
      ErrorCode.PROOF_INVALID,
      `证明版本不支持: ${String(obj.version)}`,
      null,
    );
  }
  if (
    typeof obj.file_count !== 'number' ||
    typeof obj.total_size !== 'number'
  ) {
    throw fail(ErrorCode.PROOF_INVALID, '证明中的计数字段非法', null);
  }
  if (typeof obj.generated_at !== 'string') {
    throw fail(ErrorCode.PROOF_INVALID, '证明中的时间字段非法', null);
  }
  if (typeof obj.artifact_name !== 'string') {
    throw fail(ErrorCode.PROOF_INVALID, '证明中的产物名字段非法', null);
  }
  return obj;
}

// 用解析后的证明重构用于验签的规范字节。
export function proofCanonicalFromParsed(parsed) {
  const subset = {};
  for (const f of REQUIRED_FIELDS) subset[f] = parsed[f];
  return stableJSONStringify(subset);
}

// 逐项比较证明/清单与当前扫描结果，返回差异列表（相对路径或总体摘要差异）。
export function diffModel(parsedProof, currentRecords, currentDigest) {
  const diffs = [];
  if (parsedProof.artifact_digest.toLowerCase() !== currentDigest) {
    // 先给出整体摘要差异，但仍继续逐项列出具体路径。
    // (no-op: 具体差异在下面枚举)
  }
  // 以相对路径为键。
  const oldIndex = new Map();
  // 当前证明没有单独的文件列表字段，文件列表来自重新生成的 SBOM？
  // 按需求：验证时重新计算产物摘要和文件清单，并逐项比较。证明本身含总体摘要；
  // 文件清单的基线是生成时写出的 sbom.json。因此逐项比较应在 verify 中
  // 以 sbom.json 为基准（见 CLI），这里只比较总体摘要与证明内字段。
  void oldIndex;
  void diffs;
  return parsedProof.artifact_digest.toLowerCase() === currentDigest;
}

// 比较两个「相对路径 -> 记录」集合，列出 added/removed/modified 路径。
export function diffSBOM(baseline, current) {
  const changes = [];
  const oldMap = new Map(baseline.map((r) => [r.path, r]));
  const newMap = new Map(current.map((r) => [r.path, r]));
  for (const [p, r] of newMap) {
    const old = oldMap.get(p);
    if (!old) {
      changes.push({ path: p, kind: 'added' });
    } else if (
      old.sha256 !== r.sha256 ||
      old.size !== r.size
    ) {
      changes.push({ path: p, kind: 'modified', fields: changedFields(old, r) });
    }
  }
  for (const p of oldMap.keys()) {
    if (!newMap.has(p)) changes.push({ path: p, kind: 'removed' });
  }
  changes.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  return changes;
}

function changedFields(oldR, newR) {
  const fields = [];
  if (old.sha256 ?? undefined) {
    if (oldR.sha256 !== newR.sha256) fields.push('sha256');
  }
  if (oldR.size !== newR.size) fields.push('size');
  return fields;
}

// 解析生成时写出的 SBOM 文件并做格式校验。
export function parseSBOM(raw) {
  let obj;
  try {
    obj = JSON.parse(raw.toString('utf8'));
  } catch {
    throw fail(ErrorCode.PROOF_INVALID, '清单不是合法 JSON', null);
  }
  if (!obj || typeof obj !== 'object' || !Array.isArray(obj.files)) {
    throw fail(ErrorCode.PROOF_INVALID, '清单结构非法（缺少 files 数组）', null);
  }
  for (const [i, f] of obj.files.entries()) {
    if (
      !f ||
      typeof f.path !== 'string' ||
      typeof f.sha256 !== 'string' ||
      typeof f.size !== 'number' ||
      !/^[0-9a-f]{64}$/i.test(f.sha256)
    ) {
      throw fail(ErrorCode.PROOF_INVALID, `清单第 ${i} 项记录非法`, null);
    }
  }
  return obj;
}

