// 文件读写
// ---------------------------------------------------------------------------

export function ensureDir(dir) {
  try {
    mkdirSync(dir, { recursive: true });
  } catch (err) {
    if (err.code === 'EACCES' || err.code === 'EPERM') {
      throw fail(ErrorCode.PERMISSION_DENIED, '无法创建输出目录（权限不足）', {
