  }
}

export function chmod600(p) {
  try {
    chmodSync(p, 0o600);
  } catch {
    // 权限收窄失败不阻断主流程。
  }
}

export function assertExistingPath(p, what) {
  try {
    statSync(p);
  } catch (err) {
    throw mapFsError(err, what);
  }
}

