#!/usr/bin/env node
// Prov Guard CLI：keygen / generate / verify。
// 所有面向使用者的输出均为 UTF-8 JSON；错误一律非零退出码，绝不伪装成功。
'use strict';

import {
  chmod600,
  ErrorCode,
  ProvError,
  assertExistingPath,
  buildModel,
  checkSignature,
  diffFiles,
  ensureDir,
  fail,
  generateKeyPair,
  keyFingerprint,
  loadPrivateKey,
  loadPublicKey,
  loadSignature,
  mapFsError,
  parseProof,
  proofCanonical,
  signProof,
  stableJSONStringify,
  writeOutputFile,
} from './core.mjs';
import { readFileSync } from 'node:fs';
import path from 'node:path';

// 错误码 -> 退出码（稳定、可脚本判断）。
const EXIT_CODES = {
  [ErrorCode.INPUT_NOT_FOUND]: 2,
  [ErrorCode.PERMISSION_DENIED]: 3,
  [ErrorCode.PROOF_INVALID]: 4,
  [ErrorCode.INTEGRITY_MISMATCH]: 5,
  [ErrorCode.SIGNATURE_INVALID]: 6,
  [ErrorCode.KEY_NOT_FOUND]: 7,
  USAGE: 1,
  INTERNAL: 70,
};

function main(argv) {
  const [command, ...rest] = argv;
  try {
    switch (command) {
      case 'keygen':
        return cmdKeygen(rest);
      case 'generate':
        return cmdGenerate(rest);
      case 'verify':
        return cmdVerify(rest);
      case 'help':
      case '--help':
      case '-h':
      case undefined:
        printUsage();
        return 0;
      default:
        emitError('USAGE', `未知子命令: ${command}`, null);
        return EXIT_CODES.USAGE;
    }
  } catch (err) {
    if (err instanceof ProvError) {
      emitError(err.code, err.message, err.detail ?? null);
      return EXIT_CODES[err.code] ?? EXIT_CODES.INTERNAL;
    }
    emitError('INTERNAL', err.message ?? String(err), null);
    return EXIT_CODES.INTERNAL;
  }
}

// ---------------------------------------------------------------------------
// 参数解析
// ---------------------------------------------------------------------------

function parseFlags(args, required) {
  const flags = {};
  for (let i = 0; i < args.length; i++) {
    const token = args[i];
    if (!token.startsWith('--')) {
      throw new ProvError('USAGE', `无法识别的参数: ${token}`, null);
    }
    const name = token.slice(2);
    const value = args[i + 1];
    if (value === undefined || value.startsWith('--')) {
      throw new ProvError('USAGE', `参数 --${name} 缺少取值`, null);
    }
    flags[name] = value;
    i++;
  }
  for (const name of required) {
    if (typeof flags[name] !== 'string') {
      throw new ProvError('USAGE', `缺少必需参数 --${name}`, null);
    }
  }
  return flags;
}

// ---------------------------------------------------------------------------
